import { executeWorkflowAsync } from './src/engine.js';

// Main example: condition declared before the action, but dependsOn the action.
const workflow = {
  id: 'score-routing',
  entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: ['score-gate', 'score-action'] },
    {
      id: 'score-gate',
      type: 'condition',
      dependsOn: ['score-action'],
      condition: {
        outputField: { nodeId: 'score-action', path: 'score' },
        operator: 'gte',
        valueField: 'threshold',
      },
      then: 'approved',
      else: 'rejected',
    },
    { id: 'score-action', type: 'action', operation: 'score', next: 'finish' },
    { id: 'approved', type: 'action', message: 'approved', next: 'finish' },
    { id: 'rejected', type: 'action', message: 'rejected', next: 'finish' },
    { id: 'finish', type: 'end', result: 'finished' },
  ],
};

const operations = {
  score(input) {
    const a = input.application;
    const score = 60
      + Math.min(a.years * 4, 24)
      - Math.min(a.incidents * 12, 36);
    return { score };
  },
};

const inputA = { threshold: 80, application: { years: 5, incidents: 0 } };
const inputB = { threshold: 80, application: { years: 2, incidents: 1 } };

console.log('--- A (score == threshold) ---');
const a = await executeWorkflowAsync(workflow, inputA, operations);
console.log(JSON.stringify(a, null, 2));

console.log('--- B (score < threshold) ---');
const b = await executeWorkflowAsync(workflow, inputB, operations);
console.log(JSON.stringify(b, null, 2));

// Same workflow without the dependency.
const noDep = structuredClone(workflow);
delete noDep.nodes.find(n => n.id === 'score-gate').dependsOn;
console.log('--- no dependency, input A ---');
const c = await executeWorkflowAsync(workflowWithoutDep(noDep), inputA, operations);
function workflowWithoutDep(w) { return w; }
